    const imageUrl = payload.image_urls[i];

    messages.push({
        payload: {
            event_type: 'pir_motion',
            image_url: imageUrl,
            created_at: baseTimestamp,
            metadata: {
                source: 'pir_sensor',
                burst_sequence: i + 1,
                total_burst: payload.count,
                raw_timestamp: timestamp
            }
